			array( 'תעריף הסיכון הבסיסי בפול שווה להערכת עלות הסיכון הטהור בשוק החופשי בתוספת שלא תפחת מ-25%', 'https://he.wikisource.org/wiki/תקנות_ביטוח_רכב_מנועי_(הסדר_ביטוח_שיורי_ומנגנון_לקביעת_התעריף)', 'תקנות הביטוח השיורי, תקנה 5(1)' ),
			array( 'פוליסה שהוצאה לפי הפקודה מחייבת את המבטח על אף כל דין, ומבטח אינו רשאי להתנות אותה בעשיית ביטוח נוסף', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיפים 8 ו-12' ),
		),
		'official'  => array(
			array( 'תקנות ביטוח רכב מנועי (הסדר ביטוח שיורי ומנגנון לקביעת התעריף), הנוסח המלא', 'https://he.wikisource.org/wiki/תקנות_ביטוח_רכב_מנועי_(הסדר_ביטוח_שיורי_ומנגנון_לקביעת_התעריף)' ),
			array( 'פקודת ביטוח רכב מנועי, סעיף 7', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי' ),
		),
		'sections'  => array(
			array( 'h' => 'למה קיים הסדר שיורי', 'p' => 'ביטוח חובה הוא תנאי לשימוש ברכב, ולכן המדינה אינה משאירה נהג בלי אפשרות לרכוש אותו. סעיף 7(ג) לפקודה קובע שההרשאה של כל מבטח לעסוק בביטוח רכב מותנית בהשתתפות בהסדר לביטוח מי שלא הצליח לרכוש פוליסה ישירות. התקנות משנת 2001 מגדירות ביטוח שיורי ומקימות מנהל הסדר, תאגיד שייסדו המבטחים באישור הרשות המוסמכת, שמוכר בשמם כיסוי לכל בעל רכב שפונה אליו ומפעיל משרד לפחות בכל מחוז.' ),
			array( 'h' => 'איך נקבע התעריף', 'p' => 'תקנה 5 קובעת מנגנון: תעריף הסיכון הבסיסי שווה להערכת עלות הסיכון הטהור בשוק החופשי לקבוצת סיכון דומה, בתוספת שלא תפחת מ-25%. לכך מתווספים סכום להוצאות מינהל בשיעור שמורה הרשות, ההשתתפות במימון קרנית, והצמדה למדד. סעיף 7(ד) לפקודה מסמיך את שר האוצר לקבוע את המנגנון באישור ועדת הכספים. ביטוח אופנועים בפול יכול להיקשר גם ישירות אצל מבטח, באותם תנאים ותעריפים. הרשות רשאית לשנות את שיעור התוספת לפי דוח מאגר המידע.' ),
			array( 'h' => 'מה מקבל המבוטח', 'p' => 'הפוליסה שמנפיק מנהל ההסדר היא פוליסת חובה לכל דבר: אותו כיסוי לפי סעיף 3 לפקודה, אותה תעודת ביטוח, ואותה חובה של המבטח לשפות ולפצות לפי סעיף 12. מנהל ההסדר מייצג את המבטחים כלפי המבוטחים בכל דין החל על מבטח, ובכלל זה הוראות הממונה. ביטוח לתקופה קצרה משנה מתומחר לפי תקנה 6: 5% מהתעריף השנתי לשבוע, ותוספת יומית אחר כך, ורכב מושבת מבוטח בתעריף מופחת לפי תקנה 7.' ),
		),
