	array(
		'slug'      => 'workplace-accident-definition-btl',
		'title'     => 'מהי תאונת עבודה לפי חוק הביטוח הלאומי',
		'seo_title' => 'תאונת עבודה: ההגדרה, הדרך לעבודה והחזקות בחוק | Jus-Tice',
		'seo_desc'  => 'סעיפים 79 עד 83 לחוק הביטוח הלאומי: תאונה תוך כדי ועקב העבודה, תאונה בדרך לעבודה וממנה, מתי סטייה שוללת הכרה, חזקת הסיבתיות והחריג של רשלנות.',
		'intro'     => 'הכרה בתאונה כתאונת עבודה פותחת את הדלת לדמי פגיעה, לטיפול רפואי ולגמלת נכות. ההגדרה בסעיף 79 לחוק הביטוח הלאומי, והחזקות שסביבה, קובעות אילו אירועים נכנסים ואילו נשארים בחוץ.',
		'facts'     => array(
			array( 'תאונת עבודה היא תאונה שאירעה תוך כדי עבודתו של המבוטח ועקב עבודתו אצל מעבידו או מטעמו, ובעובד עצמאי תוך כדי עיסוקו במשלח ידו ועקב עיסוקו', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 79' ),
			array( 'רואים תאונה כתאונת עבודה גם אם אירעה בדרך מהמעון לעבודה, מהעבודה למעון או ממקום עבודה אחד למשנהו, ועקב הנסיעה או ההליכה', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 80(1)' ),
			array( 'הפסקה או סטייה של ממש מהדרך המקובלת שלא למטרת העבודה שוללת את ההכרה, למעט ליווי ילד לגן או למעון ותפילת בוקר בציבור', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 81' ),
			array( 'תאונה שאירעה לעובד תוך כדי עבודה נחשבת גם עקב העבודה אם לא הוכח ההיפך; תאונה ללא גורם חיצוני נראה לעין אינה מוכרת אם השפעת העבודה הייתה פחותה הרבה מגורמים אחרים', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 83' ),
			array( 'תאונה בעת שהמבוטח נהג ברשלנות בניגוד להוראה חוקית או להוראות המעביד אינה מוכרת, אלא אם נפטר, נעשה נכה או לא היה מסוגל לעבוד עשרה ימים לפחות', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 82' ),
			array( 'לפי כל זכות, אירוע מוחי או לבבי עשוי להיות מוכר כתאונת עבודה אם נגרם מאירוע חריג, חד פעמי ובעוצמה גבוהה בעבודה, סמוך למועד האירוע', 'https://www.kolzchut.org.il/he/תאונת_עבודה', 'כל זכות' ),
		),
		'official'  => array(
