			array( 'נפגעי עבודה, אתר הביטוח הלאומי', 'https://www.btl.gov.il/benefits/Work_Injury/Pages/default.aspx' ),
			array( 'חוק הביטוח הלאומי, פרק ה', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי' ),
		),
		'sections'  => array(
			array( 'h' => 'שני התנאים: תוך כדי ועקב', 'p' => 'סעיף 79 דורש שהתאונה תארע גם תוך כדי העבודה וגם עקב העבודה. התנאי הראשון עוסק בזמן ובמקום: בשעות העבודה, במקום העבודה או בסביבתו. התנאי השני עוסק בקשר הסיבתי: סיכון שנובע מהעבודה או ממקום העבודה. סעיף 83 מקל על העובד השכיר בחזקה: תאונה תוך כדי עבודה נחשבת גם עקב העבודה כל עוד לא הוכח ההיפך. החזקה אינה חלה על אירוע פנימי, כמו אוטם, כשהשפעת העבודה עליו הייתה פחותה הרבה מגורמים אחרים.' ),
			array( 'h' => 'הדרך לעבודה וממנה', 'p' => 'סעיף 80(1) מרחיב את ההגדרה לתאונה בדרך מהמעון או ממקום הלינה לעבודה, מהעבודה הביתה, ובין שני מקומות עבודה. סעיף 81 מציב גבול: הפסקה או סטייה של ממש מהדרך המקובלת, שלא למטרה הכרוכה בעבודה, מוציאה את התאונה מההגדרה. לפי כל זכות, כניסה לבנק לעניין אישי היא הפסקה של ממש, אך מי שחזר למסלול הרגיל ונפגע אחריה מוכר. החוק מחריג במפורש שתי סטיות: ליווי ילד לגן או למעון ותפילת בוקר בציבור.' ),
			array( 'h' => 'מה עוד עלול לשלול הכרה', 'p' => 'סעיף 82 עוסק ברשלנות: תאונה בעת שהעובד נהג בניגוד להוראה חוקית או להוראות המעביד אינה מוכרת, אלא אם התוצאה הייתה מוות, נכות או אי כושר של עשרה ימים לפחות, ובתנאי שהייתה מוכרת אלמלא הרשלנות. סעיף 80 מוסיף חזקות נוספות: פגיעה בזמן הצלת גוף או רכוש במקום העבודה, ופגיעה של חבר ועד עובדים במילוי תפקידו. הביטוח הלאומי מכיר גם בפגיעות שאינן תאונה: מחלת מקצוע ומיקרוטראומה.' ),
		),
