		'sections'  => array(
			array( 'h' => 'איך מחשבים את הסכום', 'p' => 'הבסיס הוא שכר העבודה הרגיל: ההכנסה החייבת בדמי ביטוח בשלושת החודשים המלאים שקדמו לחודש שבו הופסקה העבודה, מחולקת בתשעים. דמי הפגיעה ליום הם 75% מסכום זה, עד תקרה שנגזרת מהסכום הבסיסי ועומדת ב-2026 על 1,314.25 שקלים ליום. הביטוח הלאומי בוחר בין חישוב לפי שלושת החודשים המלאים לבין חישוב הכולל את חודש הפגיעה, לפי הגבוה. עצמאי מחושב לפי ההכנסה שעליה שילם מקדמות, והיא נחשבת גמלה חוסמת.' ),
			array( 'h' => 'על אילו ימים משלמים', 'p' => 'התקופה המרבית היא 13 שבועות, כלומר 91 ימים, רצופים או לא, ממחרת יום הפגיעה. את יום הפגיעה עצמו משלם המעסיק כשכר. שני הימים שאחריו משולמים רק אם אי הכושר נמשך 12 ימים לפחות מעבר ליום הפגיעה. את דמי הפגיעה של 12 הימים הראשונים גובה הביטוח הלאומי בחזרה מהמעסיק, ולעצמאי הם אינם משולמים כלל. מהסכום מנוכים מס הכנסה ודמי ביטוח, והימים אינם יורדים ממכסת ימי המחלה של העובד.' ),
			array( 'h' => 'מה קורה אחרי 13 שבועות', 'p' => 'מי שנותרה לו נכות, או שאינו מסוגל לעבוד גם אחרי 91 יום, מגיש תביעה נפרדת לקביעת דרגת נכות מעבודה, ואם יזכה לקצבה היא תחושב מדמי הפגיעה ליום. ההכרה בתביעה לדמי פגיעה היא תנאי לתביעה הזו, ולכן מגישים אותה גם כשלא נעדרים מהעבודה, לצורך ההכרה והחזר הוצאות הטיפול. לפי כל זכות, את התביעה מגישים בתוך 12 חודשים, ותשלום רטרואקטיבי ניתן עד שנה אחורה בלבד.' ),
