			array( 'h' => 'הנוסחה בתקנה 11', 'p' => 'מסדרים את הליקויים מהגבוה לנמוך. הליקוי הראשון נספר במלואו. הליקוי השני מוכפל בחלק שנותר עד 100: אם הראשון 40%, נותרו 60%, וליקוי של 30% נותן 18%. הליקוי השלישי מוכפל ביתרה אחרי שני הראשונים: 100 פחות 40 פחות 18 הם 42, ו-10% מהם הם 4.2%. מחברים: 40 ועוד 18 ועוד 4.2 הם 62.2, ובעיגול כלפי מעלה 63%. הביטוח הלאומי מציע מחשבון לחישוב זה, ולפי כל זכות די להזין בו את סוג הוועדה ואת אחוזי הליקויים. התוצאה היא דרגת הנכות הכוללת של הפגיעה.' ),
			array( 'h' => 'התקרות והניכויים', 'p' => 'תקנה 11(ג) מגבילה: כמה פגימות באותו פרק לא יעלו על הנכות של קשיון הפרק, באותה גפה על הנכות של קיטוע, ובאותה עין על עיוורון מלא. סעיף 120 לחוק מורה לנכות ליקויים שקדמו לפגיעה, ולפי כל זכות הוועדה מפחיתה מהאחוזים את החלק שנבע ממצב קודם, למשל ליקוי בגב שהוחמר בתאונה: מי שהיו לו 10% לפני התאונה ואחריה 30%, מקבל 20% בגין הפגיעה. באיבר מזוג שכבר נפגע, הדרגה נקבעת מצירוף שתי הפגיעות בניכוי הקודמת.' ),
			array( 'h' => 'אותה שיטה בנכות כללית', 'p' => 'ועדה לנכות כללית קובעת אחוזים לפי אותו ספר מבחנים ומשקללת באותה דרך, ולפי כל זכות מחלת לב של 40% וסוכרת של 20% נותנות 52%. ההבדל הוא הליקויים המנופים: פריטים שהתקנות קבעו שאינם פוגעים בכושר ההשתכרות, כמו מצב אחרי כריתת טחול, ולכן אינם נספרים לקצבה, אך נספרים לפטור ממס הכנסה. גם המומחה בתביעת תאונת דרכים משקלל כך, ואחוזי הנכות מוזנים לנוסחת הכאב והסבל. לכן החישוב זהה בכל שלושת המסלולים.' ),
