			array( 'הרשות רשאית להתיר למבטח לנכות דמי השתתפות עצמית מפיצויי הנוהג בעד אובדן השתכרות או נזק שאינו ממוני, והמבטח חייב ליידע את המבוטח על זכותו לפוליסה ללא תניה כזו', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיף 3א' ),
			array( 'מבטח שהוציא פוליסה מוציא בו בזמן תעודת ביטוח, שאפשר להנפיק באמצעים אלקטרוניים, ורק לתקופה שבה קיימת פוליסה בת תוקף', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיף 9' ),
			array( 'אין תוקף כלפי חבות טעונת ביטוח להגבלה בפוליסה שמבוססת על גיל הנוהג או מצבו הגופני, מצב הרכב, מספר הנוסעים, משקל המטען או הזמנים והשטחים של השימוש', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיף 15' ),
			array( 'ניתן פסק דין נגד מבוטח בשל חבות מכוסה, המבטח ישלם לזכאים את הסכום כולל הוצאות וריבית, גם אם היה זכאי לבטל את הפוליסה או ביטלה', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיף 19' ),
			array( 'המבטח משלם לבית החולים את ההוצאות הסבירות של הטיפול בנפגע, עד הוצאות אשפוז של 180 יום או טיפול חוץ של שנה', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי', 'פקודת ביטוח רכב מנועי, סעיף 28' ),
		),
		'official'  => array(
			array( 'פקודת ביטוח רכב מנועי, הנוסח המלא', 'https://he.wikisource.org/wiki/פקודת_ביטוח_רכב_מנועי' ),
			array( 'חוק פיצויים לנפגעי תאונות דרכים, הנוסח המלא', 'https://he.wikisource.org/wiki/חוק_פיצויים_לנפגעי_תאונות_דרכים' ),
		),
		'sections'  => array(
			array( 'h' => 'פרק ב: חובת הביטוח והכיסוי', 'p' => 'סעיף 2 אוסר שימוש ברכב ללא פוליסה בת תוקף וקובע מאסר, קנס ופסילה. סעיף 3 מגדיר מה הפוליסה חייבת לכסות: חבות בעל הרכב והנוהג לפי חוק הפיצויים ובשל כל נזק גוף מהשימוש ברכב, וכן נזק גוף של בעל הרכב הנוהג ושל מי שנוהג בהיתרו, שמפוצים כמו כל נפגע. סעיף 3א מאפשר לרשות להתיר תניית השתתפות עצמית שמנוכה מפיצויי הנוהג בלבד, כשהמבוטח רשאי לבחור פוליסה בלעדיה. סעיף 7 מסדיר את הרשאת המבטחים ואת הפול.' ),
			array( 'h' => 'ההגנות על הנפגע', 'p' => 'סעיף 12 קובע שהפוליסה מחייבת את המבטח על אף כל דין. סעיף 15 מבטל, כלפי הנפגע, הגבלות בפוליסה שנוגעות לגיל הנהג, למצבו הגופני או הנפשי, למצב הרכב, למספר הנוסעים, למטען ולזמני השימוש. סעיף 17 מחייב נתבע למסור לנפגע את פרטי ביטוחו, וסעיף 19 מקנה לנפגע שזכה בפסק דין זכות לגבות ישירות מהמבטח, כולל הוצאות וריבית, גם אם המבטח ביטל את הפוליסה כלפי המבוטח. מבטח לעניין זה כולל את קרנית.' ),
			array( 'h' => 'בתי חולים ותעודת ביטוח', 'p' => 'סעיף 28 מטיל על המבטח לשלם לבית החולים את ההוצאות הסבירות של הטיפול בנפגע, עד 180 ימי אשפוז או שנה של טיפול חוץ, ולכן בתי החולים מבקשים אישור משטרה על התאונה. סעיף 9 קובע תעודת ביטוח נפרדת לכל רכב, שאפשר להנפיק אלקטרונית ורק לתקופה שבה הפוליסה בתוקף, וסעיף 8 אוסר על מבטח להתנות פוליסת חובה ברכישת ביטוח נוסף. פרק ה מסדיר את זכויות צד שלישי כשהמבוטח בפשיטת רגל.' ),
		),
