	array(
		'slug'      => 'policyholder-law-1981-section-map',
		'title'     => 'חוק חוזה הביטוח: מפת הסעיפים שכל מבוטח צריך להכיר',
		'seo_title' => 'חוק חוזה הביטוח, התשמ"א-1981: מפת הסעיפים | Jus-Tice',
		'seo_desc'  => 'מבנה חוק חוזה הביטוח: פוליסה וסייגים, חובת גילוי, תקופה וביטול, החמרת סיכון, תגמולים והתיישנות, סוכן הביטוח, ופרקים לביטוח חיים, נכות ונכסים.',
		'intro'     => 'הפוליסה היא חוזה, אבל לא חוזה חופשי. חוק חוזה הביטוח משנת 1981 קובע כללים שאי אפשר להתנות עליהם לרעת המבוטח, מרגע ההצעה ועד תשלום התגמולים. מפת הסעיפים עוזרת למצוא את הכלל הנכון.',
		'facts'     => array(
			array( 'חוזה ביטוח מחייב את המבטח, תמורת דמי ביטוח, לשלם בקרות מקרה הביטוח תגמולים למוטב; תנאי או סייג לחבות שלא הובלט בפוליסה, אין המבטח זכאי להסתמך עליו', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיפים 1 ו-3' ),
			array( 'הודיע המבטח על ביטול החוזה, הוא מתבטל כעבור 15 ימים ממסירת ההודעה; הודיע המבוטח, כעבור שלושה ימים', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיף 10' ),
			array( 'לא שולמו דמי הביטוח גם בתוך 15 ימים אחרי דרישה בכתב, רשאי המבטח להודיע שהחוזה יתבטל כעבור 21 ימים נוספים אם הפיגור לא יסולק', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיף 15' ),
			array( 'לעניין המשא ומתן וכריתת החוזה סוכן הביטוח הוא שלוח של המבטח, וידיעתו על עניין מהותי היא ידיעת המבטח', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיף 33' ),
			array( 'על סעיפים כמו חובת הבלטת סייגים, מרמה ומקרה מכוון אין להתנות כלל, ועל סעיפי הגילוי, ההודעה, התשלום וההתיישנות אין להתנות אלא לטובת המבוטח', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיף 39' ),
			array( 'בביטוח תאונה, מחלה ונכות שבו התגמולים בשיעור מוסכם מראש חלים כללי ביטוח חיים, ובביטוח לפי שיעור הנזק חלים כללי ביטוח נכסים כמו תחלוף', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח', 'חוק חוזה הביטוח, סעיף 54' ),
		),
		'official'  => array(
			array( 'חוק חוזה הביטוח, הנוסח המלא', 'https://he.wikisource.org/wiki/חוק_חוזה_הביטוח' ),
			array( 'תגמולי ביטוח, כל זכות', 'https://www.kolzchut.org.il/he/תגמולי_ביטוח' ),
		),
		'sections'  => array(
			array( 'h' => 'פרק א: הכללים לכל סוגי הביטוח', 'p' => 'סעיפים 1 עד 5 עוסקים בפוליסה: מסירתה, החובה להבליט סייגים וצירוף התשובות שהמבוטח נתן. סעיפים 6 עד 8 קובעים את חובת הגילוי ותוצאותיה. סעיפים 9 ו-10 עוסקים בתקופת הביטוח ובביטול: 15 יום למבטח, שלושה ימים למבוטח. סעיפים 14 ו-15 עוסקים בדמי הביטוח ובפיגור. סעיפים 17 עד 21 בהחמרת הסיכון. סעיפים 22 עד 31א בהודעה, בבירור, בתשלום ובהתיישנות. סעיפים 32 עד 36 מגדירים את סוכן הביטוח כשלוח המבטח. סעיפים 37 עד 40 עוסקים בהודעות, בייחוד תרופות, בסייגים להתניה ובתחולה.' ),
			array( 'h' => 'הפרקים לפי סוגי ביטוח', 'p' => 'פרק ב, סעיפים 41 עד 52, עוסק בביטוח חיים, ובו הגבלת טענת אי הגילוי לשלוש שנים וכללי המוטבים. פרק ג, סעיפים 53 ו-54, עוסק בביטוח תאונה, מחלה ונכות, ומפנה לכללי ביטוח חיים כשהתגמול קבוע מראש ולכללי ביטוח נכסים כשהוא לפי הנזק. פרק ד עוסק בביטוח נכסים, ובו ביטוח יתר, ביטוח כפל, ביטוח חסר, הקטנת הנזק ותחלוף, ובביטוח אחריות, כמו ביטוח צד שלישי לרכב, שבו הניזוק יכול לפנות ישירות למבטח.' ),
			array( 'h' => 'סעיף 39: מה אי אפשר לשנות בפוליסה', 'p' => 'סעיף 39 מחלק את החוק לשניים. על חלק מהסעיפים אין להתנות כלל, ובהם הבלטת הסייגים, המרמה, המקרה המכוון ומעמד הסוכן. על סעיפי הגילוי, ההודעה, המועד לתשלום, ההצמדה וההתיישנות מותר להתנות רק לטובת המבוטח. תנאי בפוליסה שסוטה מהם לרעת המבוטח אינו תקף, גם אם המבוטח חתם עליו, וסעיף 38 קובע שהתרופות שבחוק מוציאות תרופות לפי דין אחר באותם עניינים. הסעיף הוא הכלי לבדיקת כל פוליסה: השוואה בין תנאיה לכללי החוק.' ),
		),
		'related'   => array( 'notifying-insurer-insurance-event', 'three-years-insurance-limitation', 'disclosure-duty-insurance-proposal', 'insurance-claim-dispute' ),
		'pillar'    => 'tort-lawsuit-negligence-damages-israel',
	),

	array(
		'slug'      => 'fifth-chapter-work-injury-law',
		'title'     => 'פרק ה לחוק הביטוח הלאומי: ביטוח נפגעי עבודה סעיף אחרי סעיף',
		'seo_title' => 'פרק נפגעי עבודה בחוק הביטוח הלאומי: מפת הסעיפים | Jus-Tice',
		'seo_desc'  => 'מפת פרק ה לחוק הביטוח הלאומי: מבוטחים בסעיף 75, הגדרות וחזקות בסעיפים 79 עד 85, ריפוי, דמי פגיעה, גמלת נכות בסעיפים 104 עד 124, תלויים, מועדים ושיבוב.',
		'intro'     => 'ביטוח נפגעי עבודה הוא הענף הוותיק והמורכב של הביטוח הלאומי. פרק ה לחוק פורש אותו מההגדרה של תאונת עבודה ועד קצבת התלויים, ופרקים אחרים מוסיפים את מועד התביעה ואת זכות השיבוב נגד המזיק.',
		'facts'     => array(
			array( 'המבוטחים לפי הפרק הם עובד, עובד עצמאי, מי שבהכשרה או בשיקום מקצועי, נבחן לפי חוק החניכות, מתאמן לפי חוק שירות עבודה בשעת חירום, אסיר או עציר העובד, ומי ששכרו נקבע בחוק', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיף 75' ),
			array( 'סימן ב, סעיפים 79 עד 85, מגדיר פגיעה בעבודה, תאונת עבודה ומחלת מקצוע, וקובע את חזקת התאונה בדרך, הסטייה, הרשלנות וחזקת הסיבתיות', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיפים 79 עד 85' ),
			array( 'סימן ג, סעיפים 86 עד 91, מקנה ריפוי, החלמה, שיקום רפואי ושיקום מקצועי, וסימן ד, סעיפים 92 עד 102, מסדיר את דמי הפגיעה', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיפים 86 עד 102' ),
			array( 'סימן ה, סעיפים 103 עד 124, מסדיר את גמלת הנכות: הזכות לקצבה או מענק, החישוב, גמלאות מיוחדות מ-75%, היוון, קביעת דרגה, ערר וערעור, וקביעת הדרגה כתנאי לתובענה', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיפים 103 עד 124' ),
			array( 'סימן ח, סעיפים 130 עד 135, מסדיר את גמלת התלויים לבני משפחת מי שנפטר מפגיעה בעבודה', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיפים 130 עד 135' ),
			array( 'מחוץ לפרק: סעיף 296 קובע הגשת תביעה בתוך 12 חודשים, וסעיפים 328 עד 333 את זכות המוסד לתבוע מהמזיק את הגמלאות ששילם', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', 'חוק הביטוח הלאומי, סעיפים 296 ו-328' ),
		),
		'official'  => array(
			array( 'חוק הביטוח הלאומי, הנוסח המלא', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי' ),
			array( 'נפגעי עבודה, אתר הביטוח הלאומי', 'https://www.btl.gov.il/benefits/Work_Injury/Pages/default.aspx' ),
			array( 'מבוטחים בביטוח נפגעי עבודה, כל זכות', 'https://www.kolzchut.org.il/he/מבוטחים_בביטוח_נפגעי_עבודה' ),
		),
		'sections'  => array(
			array( 'h' => 'מהמבוטח ועד דמי הפגיעה', 'p' => 'סעיף 75 פותח את הפרק ברשימת המבוטחים, ובראשם עובד ועובד עצמאי. סימן ב מגדיר את המונחים: סעיף 79 את תאונת העבודה ומחלת המקצוע, סעיף 80 את התאונה בדרך, סעיף 81 את הסטייה, סעיף 82 את הרשלנות וסעיף 83 את חזקת הסיבתיות. סימן ג מבטיח ריפוי ושיקום דרך קופות החולים. סימן ד קובע את דמי הפגיעה: 13 שבועות בסעיף 92, הימים הראשונים בסעיפים 93 ו-94, ושיעור של 75% מהשכר הרגיל בסעיפים 97 ו-98.' ),
			array( 'h' => 'סימן ה: גמלת הנכות', 'p' => 'סעיף 103 מגדיר נכה עבודה ודרגה יציבה. סעיף 104 קובע את המדרגות של 9% ו-20%, סעיפים 105 עד 107 את חישוב הקצבה והמענק, סעיף 112 גמלאות מיוחדות לדרגה של 75%, וסעיף 113 את ההיוון. סעיף 118 מסדיר את קביעת הדרגה על ידי רופא או ועדה, סעיף 119 דרגה זמנית, סעיף 120 ניכוי ליקויים קודמים, סעיף 122 ערר, סעיף 123 ערעור בשאלה משפטית, וסעיף 124 קובע שקביעת הדרגה היא תנאי לתובענה. סעיף 121 מאפשר צירוף נכות קודמת מפגיעה בעבודה.' ),
			array( 'h' => 'תלויים, מועדים ושיבוב', 'p' => 'סימן ח, סעיפים 130 עד 135, מגדיר מי תלוי וקובע את שיעורי הקצבה והמענקים לאלמנה, ליתומים ולתלויים אחרים. סעיף 296 מחוץ לפרק קובע תביעה בתוך 12 חודשים ותשלום רטרואקטיבי מוגבל לשנה. סעיפים 328 עד 333 מסדירים את זכות המוסד לתבוע מהמזיק את הגמלאות, את חובת הדיווח של המבטח, את ההגנה על הנפגע בגובה 25% לפחות ואת ההיוון לצורך השיבוב. סעיף 369 מטיל על מעסיק שלא נרשם או לא שילם דמי ביטוח את עלות הגמלאות.' ),
		),
